// SPDX-License-Identifier: UNLICENSED

pragma solidity ^0.8.20;

import {Address} from "@openzeppelin/contracts/utils/Address.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IPermit2} from "src/periphery/interfaces/external/IPermit2.sol";
import {Multicall} from "src/periphery/base/Multicall.sol";
import {PeripheryStorage} from "./base/PeripheryStorage.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuardUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import {IWETH9} from "src/periphery/interfaces/external/IWETH9.sol";
import {IInfinityPoolFactory} from "src/interfaces/IInfinityPoolFactory.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {VaultActions} from "src/periphery/libraries/external/VaultActions.sol";

contract Vault is Multicall, ReentrancyGuardUpgradeable, PeripheryStorage {
    using Address for address payable;

    error OnlyWETHAllowed();
    error ETHTransferFailed();

    event Deposit(address indexed token, address indexed to, uint256 amount);
    event Withdraw(address indexed token, address indexed from, uint256 amount);
    event DepositCollateral(address indexed user, address indexed poolAddress, bool token, uint8 decimals, address source, uint256 amount);
    event WithdrawCollateral(address indexed user, address indexed poolAddress, bool token, uint8 decimals, address destination, uint256 amount);

    function __Vault_init(IPermit2 _permit2) internal {
        permit2 = _permit2;
        ReentrancyGuardUpgradeable.__ReentrancyGuard_init();
    }

    function depositERC20(
        IERC20 token,
        address to,
        uint256 amount,
        bool isPermit2, // only applicable for permit2 tokens
        uint256 nonce, // only applicable for permit2 tokens
        uint256 deadline, // only applicable for permit2 tokens
        bytes calldata signature // only applicable for permit2 tokens
    ) external nonReentrant {
        VaultActions.depositERC20(deposits, permit2, token, to, amount, isPermit2, nonce, deadline, signature);
    }

    function _depositERC20(address token, address to, uint256 amount) internal {
        VaultActions._depositERC20(deposits, token, to, amount);
    }

    function addCollateral(address tokenA, address tokenB, IERC20 token, address user, uint256 amount) external nonReentrant {
       amount = VaultActions.addCollateralCapped(deposits, collaterals, allowance, factory, tokenA, tokenB, token, user, amount);
    }

    function _increaseCollateral(address token0, address token1, IERC20 token, address user, address source, uint256 amount) internal {
        VaultActions._increaseCollateral(collaterals, factory, token0, token1, token, user, source, amount);
    }

    function _decreaseCollateral(address token0, address token1, IERC20 token, address user, address destination, uint256 amount) internal {
        VaultActions._decreaseCollateral(collaterals, factory, token0, token1, token, user, destination, amount);
    }

    function withdrawERC20(IERC20 token, address onBehalfOf, address to, uint256 amount) public nonReentrant {
        amount = VaultActions._withdrawERC20Capped(deposits, allowance, token, onBehalfOf, to, amount);
    }

    function _withdrawERC20Capped(IERC20 token, address onBehalfOf, address to, uint256 amount) internal returns (uint256){
        return VaultActions._withdrawERC20Capped(deposits, allowance, token, onBehalfOf, to, amount);
    }

    function _withdrawERC20WithoutCheckingForAllowance(IERC20 token, address onBehalfOf, uint256 amount) internal {
        VaultActions._withdrawERC20WithoutCheckingForAllowance(deposits, token, onBehalfOf, address(this), amount);
    }

    function withdrawAndUnwrapETH(address onBehalfOf, address to, uint256 amount) external nonReentrant {
        amount = VaultActions._withdrawERC20Capped(deposits, allowance, IERC20(WETH9), onBehalfOf, address(this), amount);
        IWETH9(WETH9).withdraw(amount);
        (bool success,) = to.call{value: amount}("");
        if (!success) revert ETHTransferFailed();
    }

    function _spendAllowance(address token, address owner, address spender, uint256 value) internal {
        VaultActions._spendAllowance(allowance, token, owner, spender, value);
    }

    function approveERC20(IERC20 token, address spender, uint256 amount) external nonReentrant {
        allowance[msg.sender][address(token)][spender] = amount;
    }

    function increaseAllowanceERC20(IERC20 token, address spender, uint256 amount) external nonReentrant {
        allowance[msg.sender][address(token)][spender] += amount;
    }

    receive() external payable {
        if (msg.sender != WETH9) revert OnlyWETHAllowed();
    }
}

